243	  private static func connect(socketPath: String) -> ConnectionOutcome {
244	    for _ in 0..<connectCycles {
245	      if let descriptor = SessionSocket.connect(path: socketPath) {
246	        return .connected(descriptor)
247	      }
248	      switch launchDaemon(socketPath: socketPath) {
249	      case .started, .retryableFailure:
250	        break
251	      case .fatalFailure:
252	        return .failed(SessionAttachExitCode.startupFailure)
253	      }
254	      for _ in 0..<connectAttemptsPerCycle {
255	        usleep(connectRetryMicroseconds)
256	        if let descriptor = SessionSocket.connect(path: socketPath) {
257	          return .connected(descriptor)
258	        }
259	      }
260	    }
261	    return .retry
262	  }
