5	/// The app's Settings window (⌘,). A source-list sidebar (`SettingsPane` rows) on the left, the
6	/// selected group's grouped `Form` on the right — the modern macOS System Settings layout, themed to
7	/// match the rest of the app. NavigationSplitView is deliberately avoided (it injects a titlebar
8	/// collapse-toggle and fights the fixed prefs-window sizing); `RootView` already sidesteps the native
9	/// sidebar the same way. Rows are `Button`s (immediate on click — a `List`-row `.onTapGesture` only
10	/// updates after the next event, e.g. a cursor move), and selection is a persisted `@Default` with a
11	/// hand-rolled highlight rather than `List(selection:)`, whose built-in bar fights the custom fill.
12	///
13	/// Theming mirrors the main window but via `SettingsWindowThemer` (themed window background +
14	/// transparent full-size-content title bar showing a "Settings" title) plus a panel fill that
15	/// `.ignoresSafeArea()` so SwiftUI paints the strip *behind* the title bar too — otherwise
16	/// `window.backgroundColor` alone gets reset to white by AppKit on some events and the bar flickers.
17	///
18	/// Each control binds the *same* `Defaults` key it did as a flat row, so stored values — and
19	/// everything observing them (appearance in `RootView`, copy-on-select, ⌘-click file opening) — are
20	/// unchanged; only the surface moves. The selected pane persists via `Defaults[.settingsSelectedPane]`.
21	struct SettingsView: View {
22	  // Selection is `@State`, NOT `@Default`: the `Defaults` SwiftUI wrapper invalidates the view
23	  // asynchronously (its `objectWillChange` fires from a detached `Defaults.updates` task), so a
24	  // `@Default`-driven click only repainted on the *next* runloop tick — i.e. after a cursor move.
25	  // `@State` invalidates synchronously, so the detail switches on the click. We write through to
26	  // `Defaults[.settingsSelectedPane]` for persistence and restore from it in `.onAppear`.
27	  @State private var selection: SettingsPane = Defaults[.settingsSelectedPane]
28	  @State private var hovered: SettingsPane?
29	  // Bumped on `.themeDidChange` so the themed background/highlights repaint live when the user
30	  // switches theme in the Appearance pane (the tokens are read from the `ThemeService` singleton,
31	  // which SwiftUI doesn't observe on its own here).
32	  @State private var themeTick = 0
33	
34	  var body: some View {
35	    HStack(spacing: 0) {
36	      sidebar
37	      Divider()
38	      pane.frame(width: 440)
39	    }
