41	    .background(ThemeService.shared.tokens.panel.ignoresSafeArea())
42	    .background(SettingsWindowThemer())
43	    .onReceive(NotificationCenter.default.publisher(for: .themeDidChange)) { _ in themeTick += 1 }
44	    .onAppear { selection = Defaults[.settingsSelectedPane] }
45	  }
46	
47	  private var sidebar: some View {
48	    List {
49	      ForEach(SettingsPane.allCases) { pane in
50	        Button {
51	          selection = pane
52	          Defaults[.settingsSelectedPane] = pane
53	        } label: {
