1	import Darwin
2	import MachO
3	import WorkroomSessionProtocol
4	
5	enum SessionAttachExitCode {
6	  static let transportFailure: Int32 = 90
7	  static let protocolFailure: Int32 = 91
8	  static let daemonUnavailable: Int32 = 92
9	  static let startupFailure: Int32 = 93
10	}
11	
12	enum SessionAttachClient {
13	  static let connectCycles = 3
14	  static let connectAttemptsPerCycle = 50
15	  static let connectRetryMicroseconds: useconds_t = 20000
16	  static let handshakeAttempts = 3
17	  static let handshakeRetryMicroseconds: useconds_t = 100_000
18	  static let inputBacklogLimit = 4 * 1024 * 1024
19	
20	  struct Configuration {
21	    let identifier: SessionIdentifier
22	    let socketPath: String
23	    let command: String
24	    let shell: String
25	    let resourcesDirectory: String
26	    let workingDirectory: String
27	    let metadata: [SessionEnvironmentEntry]
28	  }
29	
30	  private enum Outcome {
31	    case finished(Int32)
32	    case retry
33	    case failed(Int32)
34	  }
35	
36	  private enum ConnectionOutcome {
37	    case connected(Int32)
38	    case retry
39	    case failed(Int32)
40	  }
41	
42	  private enum DaemonLaunchOutcome {
43	    case started
44	    case retryableFailure
45	    case fatalFailure
46	  }
47	
48	  static func run(configuration: Configuration) -> Int32 {
49	    signal(SIGPIPE, SIG_IGN)
50	
51	    guard let signalPipe = SessionSignalPipe(signals: [SIGWINCH]) else {
52	      return SessionAttachExitCode.startupFailure
53	    }
54	
55	    let originalTerminal = enterRawMode()
56	    defer {
57	      if var originalTerminal {
58	        tcsetattr(STDIN_FILENO, TCSANOW, &originalTerminal)
59	      }
60	    }
61	
62	    for attempt in 0..<handshakeAttempts {
63	      switch attach(configuration: configuration, signalPipe: signalPipe) {
64	      case .finished(let status), .failed(let status):
65	        return status
66	      case .retry:
67	        if attempt + 1 < handshakeAttempts {
68	          usleep(handshakeRetryMicroseconds)
69	        }
70	      }
71	    }
72	
73	    report("could not reach the session daemon")
74	    return SessionAttachExitCode.daemonUnavailable
75	  }
76	
77	  private static func attach(configuration: Configuration, signalPipe: SessionSignalPipe) -> Outcome
78	  {
79	    let socket: Int32
80	    switch connect(socketPath: configuration.socketPath) {
81	    case .connected(let descriptor):
82	      socket = descriptor
83	    case .retry:
84	      return .retry
85	    case .failed(let status):
86	      return .failed(status)
87	    }
88	    defer { SessionIO.close(socket) }
89	    SessionIO.setNonBlocking(socket)
90	
91	    let payload = makeRequest(configuration).encoded()
92	    guard payload.count <= SessionFrame.maximumPayloadSize else {
93	      // Fail fast and specifically rather than retrying `handshakeAttempts` times against the
94	      // same oversized payload and reporting the generic, misleading "could not reach the
95	      // session daemon" — this is almost always a bloated shell environment (exported functions,
96	      // PATH bloat from asdf/direnv/nvm hooks), not a daemon problem.
97	      report(
98	        "attach request too large (\(payload.count) bytes, limit "
99	          + "\(SessionFrame.maximumPayloadSize)) — check for an oversized shell environment")
100	      return .failed(SessionAttachExitCode.protocolFailure)
101	    }
102	
103	    let connection = SessionConnection(descriptor: socket)
104	    connection.enqueue(SessionFrame(kind: .attach, payload: payload))
105	    return loop(connection: connection, signalPipe: signalPipe)
106	  }
107	
108	  private static func loop(connection: SessionConnection, signalPipe: SessionSignalPipe) -> Outcome
109	  {
110	    var isAttached = false
111	    while true {
112	      guard connection.flush() else { return transportOutcome(isAttached: isAttached) }
113	
114	      var descriptors = [
115	        pollfd(fd: signalPipe.readDescriptor, events: Int16(POLLIN), revents: 0),
116	        pollfd(
117	          fd: connection.descriptor,
118	          events: Int16(
119	            connection.hasPendingOutput ? Int32(POLLIN) | Int32(POLLOUT) : Int32(POLLIN)),
120	          revents: 0),
121	      ]
122	      if isAttached, connection.pendingByteCount < inputBacklogLimit {
123	        descriptors.append(pollfd(fd: STDIN_FILENO, events: Int16(POLLIN), revents: 0))
124	      }
125	
126	      let ready = poll(&descriptors, nfds_t(descriptors.count), -1)
127	      if ready < 0 {
128	        guard errno == EINTR else { return transportOutcome(isAttached: isAttached) }
129	        continue
130	      }
131	
132	      for entry in descriptors where entry.revents != 0 {
133	        if entry.fd == signalPipe.readDescriptor {
134	          signalPipe.drain()
135	          sendResize(connection)
136	        } else if entry.fd == STDIN_FILENO {
137	          guard forwardInput(connection) else { return .finished(0) }
138	        } else if let outcome = receive(connection, revents: entry.revents, isAttached: &isAttached)
139	        {
140	          _ = connection.flush()
141	          return outcome
142	        }
143	      }
144	    }
145	  }
146	
147	  private static func transportOutcome(isAttached: Bool) -> Outcome {
148	    isAttached ? .failed(SessionAttachExitCode.transportFailure) : .retry
149	  }
150	
151	  private static func forwardInput(_ connection: SessionConnection) -> Bool {
152	    switch SessionIO.read(STDIN_FILENO) {
153	    case .bytes(let bytes):
154	      connection.enqueue(SessionFrame(kind: .input, payload: bytes))
155	      return true
156	    case .wouldBlock:
157	      return true
158	    case .endOfFile, .failed:
159	      return false
160	    }
161	  }
162	
163	  private static func receive(
164	    _ connection: SessionConnection,
165	    revents: Int16,
166	    isAttached: inout Bool
167	  ) -> Outcome? {
168	    if revents & Int16(POLLOUT) != 0, !connection.flush() {
169	      return transportOutcome(isAttached: isAttached)
170	    }
171	    guard revents & Int16(POLLIN) != 0 || revents & Int16(POLLHUP) != 0 else { return nil }
172	
173	    var reachedEnd = false
174	    readLoop: while true {
175	      switch SessionIO.read(connection.descriptor) {
176	      case .bytes(let bytes):
177	        connection.decoder.push(bytes)
178	      case .wouldBlock:
179	        break readLoop
180	      case .endOfFile, .failed:
181	        reachedEnd = true
182	        break readLoop
183	      }
184	    }
185	
186	    while true {
187	      let frame: SessionFrame?
188	      do {
189	        frame = try connection.decoder.next()
190	      } catch {
191	        return .failed(SessionAttachExitCode.protocolFailure)
192	      }
193	      guard let frame else { break }
194	      switch frame.kind {
195	      case .attached:
196	        isAttached = true
197	      case .output:
198	        guard SessionIO.writeAll(STDOUT_FILENO, frame.payload) else {
199	          return transportOutcome(isAttached: isAttached)
200	        }
201	      case .exited:
202	        return .finished((try? SessionExitPayload.decode(frame.payload)) ?? 0)
203	      case .failure:
204	        report((try? SessionTextPayload.decode(frame.payload)) ?? "session failed")
205	        return .failed(SessionAttachExitCode.protocolFailure)
206	      case .attach, .input, .resize, .list, .info, .kill, .killAll, .sessions, .acknowledged:
207	        break
208	      }
209	    }
210	
211	    return reachedEnd ? transportOutcome(isAttached: isAttached) : nil
212	  }
213	
214	  private static func report(_ message: String) {
215	    SessionIO.writeAll(STDERR_FILENO, Array(("workroom-session: " + message + "\r\n").utf8))
216	  }
217	
218	  private static func sendResize(_ connection: SessionConnection) {
219	    let size = SessionWindowSizePolicy.attachSize(
220	      from: SessionPTY.windowSize(descriptor: STDIN_FILENO))
221	    guard SessionWindowSizePolicy.isUsable(columns: size.columns, rows: size.rows) else { return }
222	    connection.enqueue(
223	      SessionFrame(
224	        kind: .resize,
225	        payload: SessionResizePayload.encode(columns: size.columns, rows: size.rows)))
226	  }
227	
228	  private static func makeRequest(_ configuration: Configuration) -> SessionAttachRequest {
229	    let size = SessionWindowSizePolicy.attachSize(
230	      from: SessionPTY.windowSize(descriptor: STDIN_FILENO))
231	    let environment = SessionProcessEnvironment.current()
232	      .filter { !$0.key.hasPrefix("WORKROOM_SESSION_") }
233	      .map { SessionEnvironmentEntry(key: $0.key, value: $0.value) }
234	    return SessionAttachRequest(
235	      identifier: configuration.identifier,
236	      columns: size.columns,
237	      rows: size.rows,
238	      workingDirectory: configuration.workingDirectory,
239	      command: configuration.command,
240	      shell: configuration.shell,
241	      resourcesDirectory: configuration.resourcesDirectory,
242	      environment: environment,
243	      metadata: configuration.metadata)
244	  }
