static func resize(masterDescriptor: Int32, columns: UInt16, rows: UInt16) {
  var size = winsize(
    ws_row: rows == 0 ? 24 : rows,
    ws_col: columns == 0 ? 80 : columns,
    ws_xpixel: 0,
    ws_ypixel: 0)
