struct DetachedSessionsButton: View {
  let target: TerminalTarget
  @EnvironmentObject var store: AppStore
  @ObservedObject private var sessionsStore = TerminalSessionsStore.shared
  @State private var showing = false

  var body: some View {
    // The refresh task must run UNCONDITIONALLY, not just when `detached` is already non-empty:
    // it's the only thing that ever populates `detached` in the first place. Nesting it inside
    // the `if` below (as this used to) makes the button structurally unable to ever appear from a
    // cold state — `detached` starts empty, so the branch that would refresh it never mounts.
    Group {
      if !sessionsStore.detached(for: target.id).isEmpty {
        Button {
          showing.toggle()
        } label: {
          Image(systemName: "rectangle.stack")
          Text("\(sessionsStore.detached(for: target.id).count)")
        }
        .buttonStyle(.plain)
        .accessibilityIdentifier("terminal.detachedSessions")
        .accessibilityLabel(
          "\(sessionsStore.detached(for: target.id).count) detached background terminals"
        )
        .popover(isPresented: $showing, arrowEdge: .top) {
          popover
            .frame(minWidth: 280, maxWidth: 360)
            .padding(12)
        }
      }
    }
    .task(id: target.id) { await refresh() }
  }

  private var popover: some View {
    VStack(alignment: .leading, spacing: 8) {
      Text("Detached terminals").font(.headline)
      ForEach(sessionsStore.detached(for: target.id), id: \.identifier.uuidString) { session in
        HStack(alignment: .firstTextBaseline, spacing: 8) {
          VStack(alignment: .leading, spacing: 2) {
            Text(session.value(forMetadataKey: SessionMetadataKey.title) ?? "Terminal")
              .lineLimit(1)
            Text(session.workingDirectory)
              .font(.caption)
              .foregroundStyle(.secondary)
              .lineLimit(1)
              .truncationMode(.head)
          }
          Spacer(minLength: 8)
          Button("Active tab") { attachToActive(session) }
            .disabled(store.terminals.focusedTab(for: target)?.surface == nil)
          Button("New tab") { openNew(session) }
          Button("Stop", role: .destructive) { stop(session) }
        }
      }
    }
  }

  private func refresh() async {
    await sessionsStore.refresh(
      workroomID: target.id, ownedSessionIDs: store.terminals.ownedSessionIDs(for: target))
  }

  private func attachToActive(_ session: SessionDescriptor) {
    guard let id = session.identifier.uuid else { return }
    guard
      TerminalSessionAttachment.attachToActivePane(
        sessionID: id, target: target, sessions: store.terminals)
    else { return }
    showing = false
    Task { await refresh() }
  }

  private func openNew(_ session: SessionDescriptor) {
    guard let id = session.identifier.uuid else { return }
    _ = store.terminals.addTab(for: target, sessionID: id)
    showing = false
    Task { await refresh() }
  }

  private func stop(_ session: SessionDescriptor) {
    guard let id = session.identifier.uuid else { return }
    Task {
      await PersistentSessionService.shared.endSession(sessionID: id)
      await refresh()
    }
  }
}

/// that Puma ignores, surfacing as "A server is already running" on the next launch (issue #7).
/// Sends only key events — never frees a surface — so the no-mass-free-on-quit rationale in
/// `applicationWillTerminate` still holds. Bounded so a wedged server can't block the quit.
@MainActor
private func stopRunCommandsThenTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply
{
  let registry = WindowRegistry.shared
  // Mark the app as terminating so a window's own close handler doesn't also prompt/stop (#70).
  registry.isTerminating = true
  // Write the session and stop writing (issue #46). Deliberately HERE and not at the top of
  // `applicationShouldTerminate`: that method can still return `.terminateCancel` at the confirm
  // dialog, and freezing above that guard would silently kill session saving for the rest of the
  // app's life after one cancelled ⌘Q. This point is past the guard and still before any window
  // closes — which is exactly what the freeze protects, since the document is rebuilt from the
  // live windows.
  SessionCoordinator.shared.flushAndFreeze()
  // With persistence off, the daemon does NOT get torn down by quitting (unlike an in-process
  // PTY, which the OS SIGHUPs when libghostty's memory is reclaimed — see the doc comment on
  // `applicationWillTerminate`): a daemon-held shell is a separate, independent process that
  // outlives Workroom on purpose. Nothing else ever kills it once the setting is off, so without
  // this every ordinary terminal's session would leak forever — silently contradicting the quit
  // alert's own promise ("stops any running processes") the moment the preference is off.
  let shouldStopPersistentSessions = !Defaults[.backgroundSessions]
  guard registry.hasAnyLiveRunCommand || shouldStopPersistentSessions else {
    return .terminateNow
  }
  let group = DispatchGroup()
  if shouldStopPersistentSessions {
    group.enter()
    Task {
      await PersistentSessionService.shared.endAllSessions()
      group.leave()
    }
  }
  if registry.hasAnyLiveRunCommand {
    group.enter()
    // Stop every window's run commands, not just the focused one's.
    registry.gracefullyStopAllWindows(timeout: 5) { group.leave() }
  }
  group.notify(queue: .main) { sender.reply(toApplicationShouldTerminate: true) }
  return .terminateLater
}

